    mc = pick(v, 0.5, 0.3)
    return [
        N(f"Тело брошено вверх со скоростью {v0a} м/с. Чему равны скорость и модуль ускорения в верхней точке? Куда направлено ускорение (g = 10 м/с²)?", "v = 0; a = 10 м/с², вниз",
          ["В верхней точке скорость равна нулю на мгновение.", "Ускорение определяется силой тяжести и равно g, направлено вниз."], [("a = 0", "П: скорость и ускорение перепутаны")], work="solve"),
        N(f"Через какое время тело, брошенное вверх со скоростью {v1} м/с, достигнет верхней точки?", f"{fmt(v1 / 10)} с", [f"v = v₀ − gt = 0, t = v₀/g = {v1}/10 = {fmt(v1 / 10)} с."], [(f"{fmt(v1 * v1 / 20)}", "Ф: найдена высота")]),
        N(f"Найди наибольшую высоту подъёма тела, брошенного вверх со скоростью {v2} м/с.", f"{fmt(v2 * v2 / 20)} м", [f"H = v₀²/(2g) = {v2}²/20 = {fmt(v2 * v2 / 20)} м."], [(f"{fmt(v2 * v2 / 10)} м", "Ф: потеряна двойка в знаменателе"), (f"{fmt(v2 / 10)}", "Ф: найдено время подъёма")]),
        N(f"Тело брошено вверх со скоростью {v3} м/с. Найди проекцию скорости через {t3} с (ось вверх). Что означает знак?", f"{v3 - 10 * t3} м/с; " + ("тело уже движется вниз" if v3 - 10 * t3 < 0 else "тело ещё поднимается"),
          [f"v = v₀ − gt = {v3} − 10 · {t3} = {v3 - 10 * t3} м/с.", "Знак минус — движение вниз, плюс — вверх."], [(f"{v3 + 10 * t3}", "Н: знак ускорения не учтён")] + ([(f"{abs(v3 - 10 * t3)}", "Н: потерян знак скорости")] if v3 - 10 * t3 < 0 else [])),
        N(f"Через какое время после броска со скоростью {v4} м/с тело вернётся в точку броска?", f"{fmt(2 * v4 / 10)} с", [f"Подъём {fmt(v4 / 10)} с и падение столько же: 2v₀/g = {fmt(2 * v4 / 10)} с."], [(f"{fmt(v4 / 10)}", "П: учтён только подъём")]),
        N(f"Человек массой {ma} кг стоит на весах в лифте, который разгоняется вверх с ускорением {aa} м/с². Что покажут весы в ньютонах (g = 10 м/с²)?", f"{fmt(ma * (10 + aa))} Н",
          [f"Ускорение вверх: P = m(g + a) = {ma} · {10 + aa} = {fmt(ma * (10 + aa))} Н (перегрузка)."], [(f"{ma * 10}", "П: вес принят равным силе тяжести"), (f"{fmt(ma * (10 - aa))}", "Н: направление ускорения перепутано")]),
        N(f"Человек массой {mb} кг в лифте, который разгоняется вниз с ускорением {ab} м/с². Каков его вес?", f"{fmt(mb * (10 - ab))} Н", [f"Ускорение вниз: P = m(g − a) = {mb} · {10 - ab} = {fmt(mb * (10 - ab))} Н."],
          [(f"{fmt(mb * (10 + ab))}", "Н: направление ускорения перепутано")]),
        N(f"Мяч массой {fmt(mc)} кг подбросили, и он летит, не касаясь руки. Каков его вес в полёте? Исчезла ли сила тяжести?", "вес равен нулю; сила тяжести " + fmt(mc * 10) + " Н не исчезла",
          ["В полёте ускорение g, поэтому P = m(g − g) = 0 (невесомость).", "Сила тяжести mg продолжает действовать и сообщает ускорение."], [(fmt(mc * 10) + " Н", "П: вес принят равным силе тяжести")], work="solve"),
    ]


